  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  request_id TEXT,
  department_id TEXT,
  doc_title TEXT NOT NULL,
  file_name TEXT NOT NULL,
  copies INTEGER NOT NULL,
  recipients TEXT NOT NULL,
  sent_by TEXT NOT NULL,
  status TEXT NOT NULL,
  error TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (department_id) REFERENCES departments(id),
  FOREIGN KEY (request_id) REFERENCES doc_print_requests(id) ON DELETE SET NULL,
  FOREIGN KEY (sent_by) REFERENCES profiles(id),
  CHECK ((status IN ('sent', 'failed')))
);
CREATE TABLE doc_print_requests (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  doc_file_id TEXT NOT NULL,
  department_id TEXT,
  copies INTEGER NOT NULL DEFAULT 1,
  note TEXT,
  requested_by TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  printed_by TEXT,
  printed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  CHECK (((copies >= 1) AND (copies <= 999))),
  FOREIGN KEY (department_id) REFERENCES departments(id),
  FOREIGN KEY (doc_file_id) REFERENCES doc_files(id) ON DELETE CASCADE,
  CHECK ((length(note) <= 300)),
  FOREIGN KEY (printed_by) REFERENCES profiles(id),
  FOREIGN KEY (requested_by) REFERENCES profiles(id),
  CHECK ((status IN ('pending', 'printed')))
);
CREATE TABLE doc_targets (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  subject_id TEXT NOT NULL,
  grade_level_id TEXT NOT NULL,
  lesson_target INTEGER NOT NULL DEFAULT 0,
  topic_target INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (grade_level_id) REFERENCES grade_levels(id) ON DELETE CASCADE,
  CHECK ((lesson_target >= 0)),
  FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE,
  UNIQUE (subject_id, grade_level_id),
  CHECK ((topic_target >= 0))
);
CREATE TABLE doc_task_files (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  task_id TEXT NOT NULL,
  teacher_id TEXT NOT NULL,
  title TEXT NOT NULL,
  file_path TEXT NOT NULL,
  file_name TEXT NOT NULL,
  mime_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  review_status TEXT NOT NULL DEFAULT 'pending',
  review_note TEXT,
  reviewed_by TEXT,
  reviewed_at TEXT,
  PRIMARY KEY (id),
  CHECK ((review_status IN ('pending', 'approved', 'returned'))),
  FOREIGN KEY (reviewed_by) REFERENCES profiles(id) ON DELETE SET NULL,
  FOREIGN KEY (task_id) REFERENCES doc_tasks(id) ON DELETE CASCADE,
  FOREIGN KEY (teacher_id) REFERENCES profiles(id) ON DELETE CASCADE
);
CREATE TABLE doc_tasks (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  title TEXT NOT NULL,
  description TEXT,
  doc_type TEXT NOT NULL,
  due_date TEXT NOT NULL,
  department_id TEXT,
  learning_area_id TEXT,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE RESTRICT,
  FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE CASCADE,
  CHECK ((doc_type IN ('lesson_plan', 'worksheet', 'exam', 'media', 'other'))),
  FOREIGN KEY (learning_area_id) REFERENCES learning_areas(id) ON DELETE CASCADE
);
CREATE TABLE doc_topics (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  lesson_id TEXT NOT NULL,
  name TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (lesson_id) REFERENCES doc_lessons(id) ON DELETE CASCADE
);
CREATE TABLE documents (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  profile_id TEXT NOT NULL,
  category TEXT NOT NULL CHECK (category IN ('{', 'c', 'o', 'n', 't', 'r', 'a', 'c', 't', ',', 'p', 'a', 'y', 's', 'l', 'i', 'p', ',', 'i', 'd', '_', 'c', 'a', 'r', 'd', ',', 'o', 't', 'h', 'e', 'r', '}')),
  file_path TEXT NOT NULL,
  file_name TEXT NOT NULL,
  uploaded_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  FOREIGN KEY (uploaded_by) REFERENCES profiles(id) ON DELETE RESTRICT
);
CREATE TABLE duty_assignments (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  duty_point_id TEXT NOT NULL,
  staff_id TEXT NOT NULL,
  date TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE RESTRICT,
  FOREIGN KEY (duty_point_id) REFERENCES duty_points(id) ON DELETE RESTRICT,
  UNIQUE (duty_point_id, staff_id, date),
  FOREIGN KEY (staff_id) REFERENCES profiles(id) ON DELETE RESTRICT
);
CREATE TABLE duty_points (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  name TEXT NOT NULL,
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  mode TEXT NOT NULL DEFAULT 'rotating',
  fixed_staff_id TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (fixed_staff_id) REFERENCES profiles(id) ON DELETE RESTRICT,
  CHECK (((mode = 'rotating') OR (fixed_staff_id IS NOT NULL))),
  CHECK ((mode IN ('rotating', 'fixed'))),
  UNIQUE (name)
);
CREATE TABLE duty_transfer_requests (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  assignment_id TEXT NOT NULL,
  requester_id TEXT NOT NULL,
  target_staff_id TEXT NOT NULL,
  duty_point_id TEXT NOT NULL,
  date TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending_target' CHECK (status IN ('{', 'p', 'e', 'n', 'd', 'i', 'n', 'g', '_', 't', 'a', 'r', 'g', 'e', 't', ',', 'p', 'e', 'n', 'd', 'i', 'n', 'g', '_', 'a', 'd', 'm', 'i', 'n', ',', 'a', 'p', 'p', 'r', 'o', 'v', 'e', 'd', ',', 'r', 'e', 'j', 'e', 'c', 't', 'e', 'd', '_', 'b', 'y', '_', 't', 'a', 'r', 'g', 'e', 't', ',', 'r', 'e', 'j', 'e', 'c', 't', 'e', 'd', '_', 'b', 'y', '_', 'a', 'd', 'm', 'i', 'n', ',', 'c', 'a', 'n', 'c', 'e', 'l', 'l', 'e', 'd', '}')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (assignment_id) REFERENCES duty_assignments(id) ON DELETE CASCADE,
  CHECK ((target_staff_id <> requester_id)),
  FOREIGN KEY (duty_point_id) REFERENCES duty_points(id) ON DELETE RESTRICT,
  FOREIGN KEY (requester_id) REFERENCES profiles(id) ON DELETE RESTRICT,
  FOREIGN KEY (target_staff_id) REFERENCES profiles(id) ON DELETE RESTRICT
);
CREATE TABLE duty_weekly_template (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  duty_point_id TEXT NOT NULL,
  weekday INTEGER NOT NULL,
  staff_id TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE RESTRICT,
  FOREIGN KEY (duty_point_id) REFERENCES duty_points(id) ON DELETE CASCADE,
  UNIQUE (duty_point_id, weekday, staff_id),
  FOREIGN KEY (staff_id) REFERENCES profiles(id) ON DELETE RESTRICT,
  CHECK (((weekday >= 0) AND (weekday <= 6)))
);
CREATE TABLE employee_compensation (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  profile_id TEXT NOT NULL,
  salary_grade_id TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  UNIQUE (profile_id),
  FOREIGN KEY (salary_grade_id) REFERENCES salary_grades(id) ON DELETE SET NULL
);
CREATE TABLE employee_positions (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  profile_id TEXT NOT NULL,
  manager_id TEXT,
  job_title_id TEXT,
  career_path_notes TEXT,
  employee_status TEXT NOT NULL DEFAULT 'active' CHECK (employee_status IN ('{', 'o', 'n', 'b', 'o', 'a', 'r', 'd', 'i', 'n', 'g', ',', 'a', 'c', 't', 'i', 'v', 'e', ',', 's', 'u', 's', 'p', 'e', 'n', 'd', 'e', 'd', ',', 'r', 'e', 's', 'i', 'g', 'n', 'e', 'd', ',', 't', 'e', 'r', 'm', 'i', 'n', 'a', 't', 'e', 'd', '}')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  end_date TEXT,
  PRIMARY KEY (id),
  CHECK ((manager_id IS DISTINCT FROM profile_id)),
  FOREIGN KEY (job_title_id) REFERENCES position_titles(id) ON DELETE SET NULL,
  FOREIGN KEY (manager_id) REFERENCES profiles(id) ON DELETE SET NULL,
  FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  UNIQUE (profile_id)
);
CREATE TABLE employee_status_history (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  profile_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('{', 'o', 'n', 'b', 'o', 'a', 'r', 'd', 'i', 'n', 'g', ',', 'a', 'c', 't', 'i', 'v', 'e', ',', 's', 'u', 's', 'p', 'e', 'n', 'd', 'e', 'd', ',', 'r', 'e', 's', 'i', 'g', 'n', 'e', 'd', ',', 't', 'e', 'r', 'm', 'i', 'n', 'a', 't', 'e', 'd', '}')),
  reason TEXT NOT NULL,
  changed_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  effective_date TEXT NOT NULL DEFAULT (date('now')),
  PRIMARY KEY (id),
  FOREIGN KEY (changed_by) REFERENCES profiles(id) ON DELETE RESTRICT,
  FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE
);
CREATE TABLE exam_attempt_answers (
  attempt_id TEXT NOT NULL,
  question_id TEXT NOT NULL,
  choice_id TEXT,
  short_answer TEXT,
  is_correct INTEGER CHECK (is_correct IN (0,1)),
  points_awarded NUMERIC,
  answered_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (attempt_id, question_id),
  FOREIGN KEY (attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE,
  FOREIGN KEY (choice_id) REFERENCES exam_question_choices(id) ON DELETE SET NULL,
  FOREIGN KEY (question_id) REFERENCES exam_questions(id) ON DELETE RESTRICT
);
CREATE TABLE exam_attempt_events (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  attempt_id TEXT NOT NULL,
  event_type TEXT NOT NULL CHECK (event_type IN ('{', 'b', 'l', 'u', 'r', ',', 'v', 'i', 's', 'i', 'b', 'i', 'l', 'i', 't', 'y', '_', 'h', 'i', 'd', 'd', 'e', 'n', '}')),
  at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE
);
CREATE TABLE exam_attempt_grants (
  session_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  extra INTEGER NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (session_id, student_id),
  CHECK ((extra > 0)),
  FOREIGN KEY (session_id) REFERENCES exam_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE exam_attempts (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  session_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  attempt_no INTEGER NOT NULL DEFAULT 1,
  started_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  submitted_at TEXT,
  status TEXT NOT NULL DEFAULT 'in_progress' CHECK (status IN ('{', 'i', 'n', '_', 'p', 'r', 'o', 'g', 'r', 'e', 's', 's', ',', 's', 'u', 'b', 'm', 'i', 't', 't', 'e', 'd', '}')),
  question_order TEXT NOT NULL DEFAULT '[]',
  score NUMERIC,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  holder_session TEXT,
  holder_seen_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  takeover_session TEXT,
  takeover_requested_at TEXT,
  is_manual INTEGER NOT NULL DEFAULT 0 CHECK (is_manual IN (0,1)),
  manual_note TEXT,
  manual_by TEXT,
  is_scan INTEGER NOT NULL DEFAULT 0 CHECK (is_scan IN (0,1)),
  scan_extra NUMERIC,
  PRIMARY KEY (id),
  FOREIGN KEY (manual_by) REFERENCES profiles(id) ON DELETE SET NULL,
  CHECK (((NOT is_manual) OR ((manual_note IS NOT NULL) AND (trim(manual_note) <> '')))),
  CHECK (((NOT is_scan) OR is_manual)),
  FOREIGN KEY (session_id) REFERENCES exam_sessions(id) ON DELETE CASCADE,
  UNIQUE (session_id, student_id, attempt_no),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE RESTRICT
);
CREATE TABLE exam_code_state (
  session_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  fails INTEGER NOT NULL DEFAULT 0,
  locked INTEGER NOT NULL DEFAULT 0 CHECK (locked IN (0,1)),
  passed INTEGER NOT NULL DEFAULT 0 CHECK (passed IN (0,1)),
  PRIMARY KEY (session_id, student_id),
  FOREIGN KEY (session_id) REFERENCES exam_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE exam_question_choices (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  question_id TEXT NOT NULL,
  label TEXT NOT NULL,
  is_correct INTEGER NOT NULL DEFAULT 0 CHECK (is_correct IN (0,1)),
  position INTEGER NOT NULL DEFAULT 0,
  label_json TEXT NOT NULL DEFAULT '[{"type": "p", "children": [{"text": ""}]}]',
  PRIMARY KEY (id),
  FOREIGN KEY (question_id) REFERENCES exam_questions(id) ON DELETE CASCADE
);
CREATE TABLE exam_questions (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  subject_id TEXT,
  question_type TEXT NOT NULL CHECK (question_type IN ('{', 'm', 'u', 'l', 't', 'i', 'p', 'l', 'e', '_', 'c', 'h', 'o', 'i', 'c', 'e', ',', 't', 'r', 'u', 'e', '_', 'f', 'a', 'l', 's', 'e', ',', 's', 'h', 'o', 'r', 't', '_', 'a', 'n', 's', 'w', 'e', 'r', '}')),
  prompt TEXT NOT NULL,
  correct_answer TEXT,
  points NUMERIC NOT NULL DEFAULT 1,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  prompt_json TEXT NOT NULL DEFAULT '[{"type": "p", "children": [{"text": ""}]}]',
  difficulty TEXT NOT NULL DEFAULT 'medium' CHECK (difficulty IN ('{', 'e', 'a', 's', 'y', ',', 'm', 'e', 'd', 'i', 'u', 'm', ',', 'h', 'a', 'r', 'd', '}')),
  topic TEXT,
  plan_topic_id TEXT,
  tags TEXT NOT NULL DEFAULT '[]',
  PRIMARY KEY (id),
  CHECK (((question_type = 'short_answer') = (correct_answer IS NOT NULL))),
  FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE RESTRICT,
  FOREIGN KEY (plan_topic_id) REFERENCES plan_topics(id) ON DELETE RESTRICT,
  CHECK ((points > (0))),
  CHECK (((subject_id IS NOT NULL) OR (plan_topic_id IS NOT NULL))),
  FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE,
  CHECK ((json_array_length(tags) <= 10))
);
CREATE TABLE exam_seat_templates (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  department_id TEXT NOT NULL,
  name TEXT NOT NULL,
  seat_rows INTEGER NOT NULL,
  seat_cols INTEGER NOT NULL,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE CASCADE,
  FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE CASCADE,
  CHECK ((length(trim(name)) > 0)),
  CHECK (((seat_cols >= 1) AND (seat_cols <= 30))),
  CHECK (((seat_rows >= 1) AND (seat_rows <= 30)))
);
CREATE TABLE exam_security_events (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  session_id TEXT NOT NULL,
  attempt_id TEXT,
  student_id TEXT,
  event_type TEXT NOT NULL,
  device TEXT,
  ip TEXT,
  actor TEXT,
  at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE,
  CHECK ((event_type IN ('login_blocked', 'takeover_requested', 'takeover_approved', 'code_failed', 'code_locked', 'code_unlocked', 'strict_disabled', 'reset_blocked'))),
  FOREIGN KEY (session_id) REFERENCES exam_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE exam_session_codes (
  session_id TEXT NOT NULL,
  code TEXT NOT NULL,
  PRIMARY KEY (session_id),
  FOREIGN KEY (session_id) REFERENCES exam_sessions(id) ON DELETE CASCADE
);
CREATE TABLE exam_session_practice_questions (
  session_id TEXT NOT NULL,
  question_id TEXT NOT NULL,
  position INTEGER NOT NULL,
  PRIMARY KEY (session_id, question_id),
  FOREIGN KEY (question_id) REFERENCES exam_questions(id) ON DELETE RESTRICT,
  FOREIGN KEY (session_id) REFERENCES exam_sessions(id) ON DELETE CASCADE
);
CREATE TABLE exam_session_questions (
  session_id TEXT NOT NULL,
  question_id TEXT NOT NULL,
  position INTEGER NOT NULL,
  points NUMERIC NOT NULL,
  PRIMARY KEY (session_id, question_id),
  CHECK ((points > (0))),
  FOREIGN KEY (question_id) REFERENCES exam_questions(id) ON DELETE RESTRICT,
  FOREIGN KEY (session_id) REFERENCES exam_sessions(id) ON DELETE CASCADE
);
CREATE TABLE exam_session_rooms (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  session_id TEXT NOT NULL,
  position INTEGER NOT NULL,
  room_id TEXT,
  seat_rows INTEGER,
  seat_cols INTEGER,
  template_id TEXT,
  PRIMARY KEY (id),
  CHECK (((seat_rows IS NULL) = (seat_cols IS NULL))),
  CHECK (("position" >= 1)),
  FOREIGN KEY (room_id) REFERENCES rooms(id) ON DELETE SET NULL,
  CHECK (((seat_cols >= 1) AND (seat_cols <= 30))),
  CHECK (((seat_rows >= 1) AND (seat_rows <= 30))),
  FOREIGN KEY (session_id) REFERENCES exam_sessions(id) ON DELETE CASCADE,
  UNIQUE (session_id, "position"),
  FOREIGN KEY (template_id) REFERENCES exam_seat_templates(id) ON DELETE SET NULL
);
CREATE TABLE exam_session_seating (
  session_id TEXT NOT NULL,
  seat_rows INTEGER NOT NULL,
  seat_cols INTEGER NOT NULL,
  template_id TEXT,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (session_id),
  CHECK (((seat_cols >= 1) AND (seat_cols <= 30))),
  CHECK (((seat_rows >= 1) AND (seat_rows <= 30))),
  FOREIGN KEY (session_id) REFERENCES exam_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (template_id) REFERENCES exam_seat_templates(id) ON DELETE SET NULL
);
CREATE TABLE exam_session_seats (
  session_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  seat_row INTEGER NOT NULL,
  seat_col INTEGER NOT NULL,
  session_room_id TEXT NOT NULL,
  PRIMARY KEY (session_id, student_id),
  CHECK ((seat_col >= 1)),
  CHECK ((seat_row >= 1)),
  FOREIGN KEY (session_id) REFERENCES exam_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (session_room_id) REFERENCES exam_session_rooms(id) ON DELETE CASCADE,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE exam_session_sets (
  session_id TEXT NOT NULL,
  topic_set_id TEXT NOT NULL,
  subject_id TEXT NOT NULL,
  gradebook_item_id TEXT,
  PRIMARY KEY (session_id, topic_set_id),
  FOREIGN KEY (gradebook_item_id) REFERENCES score_items(id) ON DELETE SET NULL,
  FOREIGN KEY (session_id) REFERENCES exam_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE,
  FOREIGN KEY (topic_set_id) REFERENCES exam_topic_sets(id) ON DELETE RESTRICT
);
CREATE TABLE exam_session_special_seats (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  session_id TEXT NOT NULL,
  session_room_id TEXT NOT NULL,
  special_no INTEGER NOT NULL,
  student_id TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (session_id) REFERENCES exam_sessions(id) ON DELETE CASCADE,
  UNIQUE (session_id, student_id),
  FOREIGN KEY (session_room_id) REFERENCES exam_session_rooms(id) ON DELETE CASCADE,
  UNIQUE (session_room_id, special_no),
  CHECK (((special_no >= 1) AND (special_no <= 10))),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE SET NULL
);
CREATE TABLE exam_session_targets (
  session_id TEXT NOT NULL,
  teaching_assignment_id TEXT NOT NULL,
  PRIMARY KEY (session_id, teaching_assignment_id),
  FOREIGN KEY (session_id) REFERENCES exam_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (teaching_assignment_id) REFERENCES teaching_assignments(id) ON DELETE CASCADE
);
CREATE TABLE exam_sessions (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  subject_id TEXT NOT NULL,
  teacher_id TEXT NOT NULL,
  title TEXT NOT NULL,
  opens_at TEXT,
  closes_at TEXT,
  duration_minutes INTEGER,
  max_attempts INTEGER NOT NULL DEFAULT 1,
  shuffle_questions INTEGER NOT NULL DEFAULT 1 CHECK (shuffle_questions IN (0,1)),
  shuffle_choices INTEGER NOT NULL DEFAULT 1 CHECK (shuffle_choices IN (0,1)),
  sync_to_gradebook INTEGER NOT NULL DEFAULT 0 CHECK (sync_to_gradebook IN (0,1)),
  gradebook_item_id TEXT,
  review_released INTEGER NOT NULL DEFAULT 0 CHECK (review_released IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  strict_mode INTEGER NOT NULL DEFAULT 1 CHECK (strict_mode IN (0,1)),
  topic_set_id TEXT NOT NULL,
  exam_type TEXT,
  round INTEGER,
  is_enabled INTEGER NOT NULL DEFAULT 1 CHECK (is_enabled IN (0,1)),
  room_id TEXT,
  PRIMARY KEY (id),
  CHECK ((closes_at > opens_at)),
  CHECK (((duration_minutes IS NULL) OR (duration_minutes > 0))),
  FOREIGN KEY (gradebook_item_id) REFERENCES score_items(id) ON DELETE SET NULL,
  CHECK ((max_attempts > 0)),
  FOREIGN KEY (room_id) REFERENCES rooms(id) ON DELETE SET NULL,
  CHECK (((round IS NULL) OR (round > 0))),
  CHECK (((opens_at IS NULL) = (closes_at IS NULL))),
  FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE,
  FOREIGN KEY (teacher_id) REFERENCES profiles(id) ON DELETE RESTRICT,
  FOREIGN KEY (topic_set_id) REFERENCES exam_topic_sets(id) ON DELETE RESTRICT
);
CREATE TABLE exam_topic_set_topics (
  set_id TEXT NOT NULL,
  topic_id TEXT NOT NULL,
  PRIMARY KEY (set_id, topic_id),
  FOREIGN KEY (set_id) REFERENCES exam_topic_sets(id) ON DELETE CASCADE,
  FOREIGN KEY (topic_id) REFERENCES plan_topics(id) ON DELETE RESTRICT
);
CREATE TABLE exam_topic_sets (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  teacher_id TEXT NOT NULL,
  subject_id TEXT NOT NULL,
  approval_status TEXT NOT NULL DEFAULT 'draft' CHECK (approval_status IN ('{', 'd', 'r', 'a', 'f', 't', ',', 'p', 'e', 'n', 'd', 'i', 'n', 'g', ',', 'a', 'p', 'p', 'r', 'o', 'v', 'e', 'd', ',', 'r', 'e', 'j', 'e', 'c', 't', 'e', 'd', '}')),
  approval_note TEXT,
  approved_by TEXT,
  approved_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  teaching_assignment_id TEXT,
  no_exam INTEGER NOT NULL DEFAULT 0 CHECK (no_exam IN (0,1)),
  exam_type TEXT,
  round INTEGER,
  PRIMARY KEY (id),
  FOREIGN KEY (approved_by) REFERENCES profiles(id) ON DELETE SET NULL,
  CHECK (((round IS NULL) OR (round > 0))),
  FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE,
  FOREIGN KEY (teacher_id) REFERENCES profiles(id) ON DELETE CASCADE,
  FOREIGN KEY (teaching_assignment_id) REFERENCES teaching_assignments(id) ON DELETE CASCADE
);
CREATE TABLE grade_levels (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  department_id TEXT NOT NULL,
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  is_entry_point INTEGER NOT NULL DEFAULT 0 CHECK (is_entry_point IN (0,1)),
  PRIMARY KEY (id),
  UNIQUE (department_id, code),
  FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE RESTRICT
);
CREATE TABLE guardianships (
  parent_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  PRIMARY KEY (parent_id, student_id),
  FOREIGN KEY (parent_id) REFERENCES profiles(id) ON DELETE CASCADE,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE kg_assessment_topics (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  grade_level_id TEXT NOT NULL,
  domain TEXT NOT NULL CHECK (domain IN ('{', 'p', 'h', 'y', 's', 'i', 'c', 'a', 'l', ',', 'e', 'm', 'o', 't', 'i', 'o', 'n', 'a', 'l', ',', 's', 'o', 'c', 'i', 'a', 'l', ',', 'c', 'o', 'g', 'n', 'i', 't', 'i', 'v', 'e', '}')),
  academic_year INTEGER NOT NULL,
  name_th TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  UNIQUE (grade_level_id, academic_year, domain, sort_order),
  FOREIGN KEY (grade_level_id) REFERENCES grade_levels(id) ON DELETE RESTRICT
);
CREATE TABLE learning_areas (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  parent_id TEXT,
  PRIMARY KEY (id),
  UNIQUE (code),
  FOREIGN KEY (parent_id) REFERENCES learning_areas(id) ON DELETE RESTRICT
);
CREATE TABLE learning_units (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  grade_level_id TEXT NOT NULL,
  academic_year INTEGER NOT NULL,
  name_th TEXT NOT NULL,
  name_en TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  UNIQUE (grade_level_id, academic_year, sort_order),
  FOREIGN KEY (grade_level_id) REFERENCES grade_levels(id) ON DELETE RESTRICT
);
CREATE TABLE leave_requests (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  profile_id TEXT NOT NULL,
  leave_type_id TEXT NOT NULL,
  start_date TEXT NOT NULL,
  end_date TEXT NOT NULL,
  days INTEGER GENERATED ALWAYS AS (CAST(julianday(end_date) - julianday(start_date) + 1 AS INTEGER)) VIRTUAL,
  reason TEXT NOT NULL,
  attachment_path TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('{', 'p', 'e', 'n', 'd', 'i', 'n', 'g', ',', 'a', 'p', 'p', 'r', 'o', 'v', 'e', 'd', ',', 'r', 'e', 'j', 'e', 'c', 't', 'e', 'd', ',', 'c', 'a', 'n', 'c', 'e', 'l', 'l', 'e', 'd', '}')),
  approved_by TEXT,
  approved_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (approved_by) REFERENCES profiles(id) ON DELETE SET NULL,
  CHECK ((end_date >= start_date)),
  FOREIGN KEY (leave_type_id) REFERENCES leave_types(id) ON DELETE RESTRICT,
  FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE RESTRICT
);
CREATE TABLE leave_types (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  max_days_per_year INTEGER,
  requires_attachment_after_days INTEGER,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  UNIQUE (code)
);
CREATE TABLE line_link_codes (
  code TEXT NOT NULL,
  profile_id TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  used_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (code),
  FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE
);
CREATE TABLE line_notifications (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  profile_id TEXT NOT NULL,
  message TEXT NOT NULL,
  score_item_id TEXT,
  status TEXT NOT NULL DEFAULT 'pending',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  sent_at TEXT,
  error TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  FOREIGN KEY (score_item_id) REFERENCES score_items(id) ON DELETE SET NULL,
  CHECK ((status IN ('pending', 'sending', 'sent', 'error')))
);
CREATE TABLE password_reset_attempts (
  login_id TEXT NOT NULL,
  attempt_count INTEGER NOT NULL DEFAULT 0,
  first_attempt_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (login_id)
);
CREATE TABLE period_attendance_records (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  schedule_entry_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  date TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('{', 'p', 'r', 'e', 's', 'e', 'n', 't', ',', 'l', 'a', 't', 'e', ',', 'a', 'b', 's', 'e', 'n', 't', ',', 'l', 'e', 'a', 'v', 'e', '}')),
  note TEXT,
  recorded_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (recorded_by) REFERENCES profiles(id) ON DELETE RESTRICT,
  UNIQUE (schedule_entry_id, date, student_id),
  FOREIGN KEY (schedule_entry_id) REFERENCES schedule_entries(id) ON DELETE RESTRICT,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE RESTRICT
);
CREATE TABLE period_definitions (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  department_id TEXT NOT NULL,
  day_of_week INTEGER NOT NULL,
  period_no INTEGER NOT NULL,
  period_type TEXT NOT NULL,
  label TEXT NOT NULL,
  start_time TEXT NOT NULL,
  end_time TEXT NOT NULL,
  grade_level_id TEXT,
  PRIMARY KEY (id),
  CHECK ((end_time > start_time)),
  CHECK (((day_of_week >= 1) AND (day_of_week <= 6))),
  FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE RESTRICT,
  FOREIGN KEY (grade_level_id) REFERENCES grade_levels(id) ON DELETE CASCADE,
  CHECK ((period_no > 0)),
  CHECK ((period_type IN ('teaching', 'break')))
);
CREATE TABLE plan_lesson_files (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  lesson_id TEXT NOT NULL,
  doc_file_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (doc_file_id) REFERENCES doc_files(id) ON DELETE CASCADE,
  UNIQUE (lesson_id, doc_file_id),
  FOREIGN KEY (lesson_id) REFERENCES plan_lessons(id) ON DELETE CASCADE
);
CREATE TABLE plan_lesson_subjects (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  lesson_id TEXT NOT NULL,
  subject_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (lesson_id) REFERENCES plan_lessons(id) ON DELETE CASCADE,
  UNIQUE (lesson_id, subject_id),
  FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE
);
CREATE TABLE plan_lessons (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  subject_id TEXT NOT NULL,
  grade_level_id TEXT NOT NULL,
  name TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (grade_level_id) REFERENCES grade_levels(id) ON DELETE CASCADE,
  CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  FOREIGN KEY (subject_id) REFERENCES plan_subjects(id) ON DELETE CASCADE
);
CREATE TABLE plan_subjects (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  department_id TEXT NOT NULL,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  color TEXT,
  icon TEXT,
  PRIMARY KEY (id),
  CHECK ((color IN ('rose', 'blue', 'emerald', 'amber', 'orange', 'violet', 'cyan', 'pink', 'slate'))),
  FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE CASCADE,
  UNIQUE (department_id, name),
  CHECK ((icon IN ('book', 'flask', 'calculator', 'globe', 'language', 'music', 'brush', 'sport', 'laptop', 'leaf', 'planet', 'people', 'heart'))),
  CHECK (((length(name) >= 1) AND (length(name) <= 200)))
);
CREATE TABLE plan_topic_files (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  topic_id TEXT NOT NULL,
  doc_file_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (doc_file_id) REFERENCES doc_files(id) ON DELETE CASCADE,
  UNIQUE (topic_id, doc_file_id),
  FOREIGN KEY (topic_id) REFERENCES plan_topics(id) ON DELETE CASCADE
);
CREATE TABLE plan_topics (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  lesson_id TEXT NOT NULL,
  name TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (lesson_id) REFERENCES plan_lessons(id) ON DELETE CASCADE,
  CHECK (((length(name) >= 1) AND (length(name) <= 200)))
);
CREATE TABLE pos_products (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  price INTEGER NOT NULL,
  category TEXT,
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  image_path TEXT,
  PRIMARY KEY (id),
  CHECK (((category IS NULL) OR (trim(category) <> ''))),
  CHECK ((code GLOB 'P-[0-9][0-9][0-9][0-9][0-9][0-9]*')),
  UNIQUE (code),
  CHECK ((trim(name) <> '')),
  CHECK (((price >= 1) AND (price <= 500)))
);
CREATE TABLE pos_terminal_pin_attempts (
  terminal_id TEXT NOT NULL,
  failed_attempts INTEGER NOT NULL DEFAULT 0,
  locked_until TEXT,
  PRIMARY KEY (terminal_id),
  FOREIGN KEY (terminal_id) REFERENCES pos_terminals(id) ON DELETE CASCADE
);
CREATE TABLE pos_terminals (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  name TEXT NOT NULL,
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  profile_id TEXT,
  PRIMARY KEY (id),
  CHECK ((trim(name) <> '')),
  UNIQUE (name),
  FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE SET NULL,
  UNIQUE (profile_id)
);
CREATE TABLE position_titles (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  UNIQUE (code)
);
CREATE TABLE practice_attempt_answers (
  attempt_id TEXT NOT NULL,
  question_id TEXT NOT NULL,
  choice_id TEXT,
  short_answer TEXT,
  is_correct INTEGER CHECK (is_correct IN (0,1)),
  points_awarded NUMERIC,
  answered_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (attempt_id, question_id),
  FOREIGN KEY (attempt_id) REFERENCES practice_attempts(id) ON DELETE CASCADE,
  FOREIGN KEY (choice_id) REFERENCES exam_question_choices(id) ON DELETE SET NULL,
  FOREIGN KEY (question_id) REFERENCES exam_questions(id) ON DELETE RESTRICT
);
CREATE TABLE practice_attempts (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  set_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  started_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  submitted_at TEXT,
  status TEXT NOT NULL DEFAULT 'in_progress' CHECK (status IN ('{', 'i', 'n', '_', 'p', 'r', 'o', 'g', 'r', 'e', 's', 's', ',', 's', 'u', 'b', 'm', 'i', 't', 't', 'e', 'd', '}')),
  question_order TEXT NOT NULL DEFAULT '[]',
  score NUMERIC,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (set_id) REFERENCES practice_sets(id) ON DELETE CASCADE,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE RESTRICT
);
CREATE TABLE practice_set_questions (
  set_id TEXT NOT NULL,
  question_id TEXT NOT NULL,
  position INTEGER NOT NULL,
  PRIMARY KEY (set_id, question_id),
  FOREIGN KEY (question_id) REFERENCES exam_questions(id) ON DELETE RESTRICT,
  FOREIGN KEY (set_id) REFERENCES practice_sets(id) ON DELETE CASCADE
);
CREATE TABLE practice_sets (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  subject_id TEXT,
  created_by TEXT NOT NULL,
  is_teacher_curated INTEGER NOT NULL DEFAULT 1 CHECK (is_teacher_curated IN (0,1)),
  title TEXT,
  topic TEXT,
  difficulty TEXT CHECK (difficulty IN ('{', 'e', 'a', 's', 'y', ',', 'm', 'e', 'd', 'i', 'u', 'm', ',', 'h', 'a', 'r', 'd', '}')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  topic_id TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE RESTRICT,
  CHECK (((subject_id IS NOT NULL) OR (topic_id IS NOT NULL))),
  FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE,
  FOREIGN KEY (topic_id) REFERENCES plan_topics(id) ON DELETE RESTRICT
);
CREATE TABLE premises_exit_requests (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  profile_id TEXT NOT NULL,
  date TEXT NOT NULL,
  reason TEXT NOT NULL,
  exit_time TEXT NOT NULL,
  exit_lat REAL,
  exit_lng REAL,
  return_time TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('{', 'p', 'e', 'n', 'd', 'i', 'n', 'g', ',', 'a', 'p', 'p', 'r', 'o', 'v', 'e', 'd', ',', 'r', 'e', 'j', 'e', 'c', 't', 'e', 'd', '}')),
  approved_by TEXT,
  approved_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  planned_return_time TEXT,
  no_return INTEGER NOT NULL DEFAULT 0 CHECK (no_return IN (0,1)),
  PRIMARY KEY (id),
  FOREIGN KEY (approved_by) REFERENCES profiles(id) ON DELETE SET NULL,
  FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE RESTRICT
);
CREATE TABLE profile_roles (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  profile_id TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('{', 's', 'u', 'p', 'e', 'r', '_', 'a', 'd', 'm', 'i', 'n', ',', 'd', 'i', 'r', 'e', 'c', 't', 'o', 'r', ',', 's', 't', 'a', 'f', 'f', ',', 'd', 'e', 'p', 't', '_', 'h', 'e', 'a', 'd', ',', 't', 'e', 'a', 'c', 'h', 'e', 'r', ',', 's', 't', 'u', 'd', 'e', 'n', 't', ',', 'p', 'a', 'r', 'e', 'n', 't', ',', 'd', 'e', 'p', 't', '_', 'd', 'i', 'r', 'e', 'c', 't', 'o', 'r', ',', 'c', 'a', 's', 'h', 'i', 'e', 'r', '}')),
  position_title_id TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  CHECK (((role = 'dept_head') = (position_title_id IS NOT NULL))),
  FOREIGN KEY (position_title_id) REFERENCES position_titles(id) ON DELETE RESTRICT,
  FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE
);
CREATE TABLE profiles (
  id TEXT NOT NULL,
  department_id TEXT,
  prefix TEXT,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  email TEXT,
  phone TEXT,
  line_user_id TEXT,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  national_id TEXT,
  date_of_birth TEXT,
  teacher_code TEXT,
  learning_area_id TEXT,
  must_change_password INTEGER NOT NULL DEFAULT 0 CHECK (must_change_password IN (0,1)),
  avatar_path TEXT,
  character_options TEXT,
  house_no TEXT,
  village_no TEXT,
  alley TEXT,
  road TEXT,
  subdistrict TEXT,
  district TEXT,
  province TEXT,
  postal_code TEXT,
  line_notifications_enabled INTEGER NOT NULL DEFAULT 1 CHECK (line_notifications_enabled IN (0,1)),
  banner_path TEXT,
  banner_focus_x INTEGER NOT NULL DEFAULT 50,
  banner_focus_y INTEGER NOT NULL DEFAULT 50,
  banner_colors TEXT,
  PRIMARY KEY (id),
  CHECK (((banner_colors IS NULL) OR (json_array_length(banner_colors) = 5))),
  CHECK (((banner_focus_x >= 0) AND (banner_focus_x <= 100))),
  CHECK (((banner_focus_y >= 0) AND (banner_focus_y <= 100))),
  FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE RESTRICT,
  FOREIGN KEY (id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (learning_area_id) REFERENCES learning_areas(id) ON DELETE RESTRICT,
  UNIQUE (line_user_id),
  UNIQUE (national_id),
  UNIQUE (teacher_code)
);
CREATE TABLE push_subscriptions (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  profile_id TEXT NOT NULL,
  endpoint TEXT NOT NULL,
  p256dh TEXT NOT NULL,
  auth TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  UNIQUE (endpoint),
  FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE
);
CREATE TABLE rooms (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  department_id TEXT NOT NULL,
  name TEXT NOT NULL,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE RESTRICT,
  UNIQUE (department_id, name),
  CHECK ((length(trim(name)) > 0))
);
CREATE TABLE salary_grades (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  min_salary NUMERIC,
  max_salary NUMERIC,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  CHECK (((min_salary IS NULL) OR (max_salary IS NULL) OR (max_salary >= min_salary))),
  UNIQUE (code)
);
CREATE TABLE schedule_entries (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  teaching_assignment_id TEXT NOT NULL,
  day_of_week INTEGER NOT NULL,
  period_no INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  room_id TEXT,
  PRIMARY KEY (id),
  CHECK (((day_of_week >= 1) AND (day_of_week <= 6))),
  CHECK ((period_no > 0)),
  FOREIGN KEY (room_id) REFERENCES rooms(id) ON DELETE RESTRICT,
  UNIQUE (teaching_assignment_id, day_of_week, period_no),
  FOREIGN KEY (teaching_assignment_id) REFERENCES teaching_assignments(id) ON DELETE CASCADE
);
CREATE TABLE school_settings (
  id INTEGER NOT NULL DEFAULT 1,
  name_th TEXT NOT NULL DEFAULT '',
  name_en TEXT,
  logo_path TEXT,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  time_tracking_roles TEXT NOT NULL DEFAULT '[]',
  attendance_digest_time TEXT,
  attendance_digest_last_sent TEXT,
  staff_attendance_digest_time TEXT,
  staff_attendance_digest_last_sent TEXT,
  promptpay_id TEXT,
  promptpay_qr_path TEXT,
  PRIMARY KEY (id),
  CHECK ((id = 1))
);
CREATE TABLE score_items (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  teaching_assignment_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('{', 'c', 'o', 'l', 'l', 'e', 'c', 't', ',', 'e', 'x', 'a', 'm', '}')),
  label TEXT NOT NULL,
  max_score NUMERIC NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  description TEXT,
  due_date TEXT,
  publish_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  requires_submission INTEGER NOT NULL DEFAULT 0 CHECK (requires_submission IN (0,1)),
  notified_at TEXT,
  PRIMARY KEY (id),
  CHECK ((max_score > (0))),
  FOREIGN KEY (teaching_assignment_id) REFERENCES teaching_assignments(id) ON DELETE CASCADE
);
CREATE TABLE staff_attendance_overrides (
  profile_id TEXT NOT NULL,
  date TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('{', 'p', 'r', 'e', 's', 'e', 'n', 't', ',', 'l', 'a', 't', 'e', ',', 'a', 'b', 's', 'e', 'n', 't', ',', 'l', 'e', 'a', 'v', 'e', '}')),
  reason TEXT NOT NULL,
  set_by TEXT NOT NULL,
  set_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (profile_id, date),
  FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
  CHECK ((length(trim(reason)) > 0)),
  FOREIGN KEY (set_by) REFERENCES profiles(id)
);
CREATE TABLE student_cards (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  student_id TEXT NOT NULL,
  card_uid TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  created_by TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  frozen_by TEXT,
  kind TEXT NOT NULL,
  PRIMARY KEY (id),
  CHECK (((card_uid = trim(card_uid)) AND (card_uid <> ''))),
  UNIQUE (card_uid),
  FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL,
  CHECK ((frozen_by IN ('parent', 'school'))),
  CHECK ((kind IN ('qr', 'barcode', 'rfid'))),
  CHECK ((status IN ('active', 'frozen', 'replaced'))),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE student_classroom_enrollments (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  student_id TEXT NOT NULL,
  classroom_id TEXT NOT NULL,
  academic_year INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (classroom_id) REFERENCES classrooms(id) ON DELETE RESTRICT,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE student_cohort_enrollments (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  student_id TEXT NOT NULL,
  cohort_id TEXT NOT NULL,
  study_plan_id TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (cohort_id) REFERENCES curriculum_cohorts(id) ON DELETE RESTRICT,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (study_plan_id) REFERENCES study_plans(id) ON DELETE RESTRICT
);
CREATE TABLE student_contacts (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  student_id TEXT NOT NULL,
  relationship TEXT NOT NULL CHECK (relationship IN ('{', 'f', 'a', 't', 'h', 'e', 'r', ',', 'm', 'o', 't', 'h', 'e', 'r', ',', 'o', 't', 'h', 'e', 'r', '}')),
  relationship_note TEXT,
  is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0,1)),
  prefix TEXT,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  phone TEXT,
  email TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  house_no TEXT,
  village_no TEXT,
  alley TEXT,
  road TEXT,
  subdistrict TEXT,
  district TEXT,
  province TEXT,
  postal_code TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE student_grade_status (
  teaching_assignment_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  status TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (teaching_assignment_id, student_id),
  CHECK ((status IN ('ร', 'มส'))),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE RESTRICT,
  FOREIGN KEY (teaching_assignment_id) REFERENCES teaching_assignments(id) ON DELETE CASCADE
);
CREATE TABLE student_guardian_financials (
  contact_id TEXT NOT NULL,
  occupation TEXT,
  workplace TEXT,
  monthly_income NUMERIC,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (contact_id),
  FOREIGN KEY (contact_id) REFERENCES student_contacts(id) ON DELETE CASCADE
);
CREATE TABLE student_item_scores (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  score_item_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  score NUMERIC NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  feedback TEXT,
  PRIMARY KEY (id),
  CHECK ((score >= (0))),
  FOREIGN KEY (score_item_id) REFERENCES score_items(id) ON DELETE CASCADE,
  UNIQUE (score_item_id, student_id),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE RESTRICT
);
CREATE TABLE student_leave_requests (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  student_id TEXT NOT NULL,
  submitted_by TEXT NOT NULL,
  start_date TEXT NOT NULL,
  end_date TEXT NOT NULL,
  days INTEGER GENERATED ALWAYS AS (CAST(julianday(end_date) - julianday(start_date) + 1 AS INTEGER)) VIRTUAL,
  reason TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('{', 'p', 'e', 'n', 'd', 'i', 'n', 'g', ',', 'a', 'p', 'p', 'r', 'o', 'v', 'e', 'd', ',', 'r', 'e', 'j', 'e', 'c', 't', 'e', 'd', ',', 'c', 'a', 'n', 'c', 'e', 'l', 'l', 'e', 'd', '}')),
  approved_by TEXT,
  approved_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  leave_type_id TEXT,
  attachment_path TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (approved_by) REFERENCES profiles(id) ON DELETE SET NULL,
  CHECK ((end_date >= start_date)),
  FOREIGN KEY (leave_type_id) REFERENCES leave_types(id) ON DELETE RESTRICT,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE RESTRICT,
  FOREIGN KEY (submitted_by) REFERENCES profiles(id) ON DELETE RESTRICT
);
CREATE TABLE student_pass_fail_scores (
  teaching_assignment_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  passed INTEGER NOT NULL CHECK (passed IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  feedback TEXT,
  PRIMARY KEY (teaching_assignment_id, student_id),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE RESTRICT,
  FOREIGN KEY (teaching_assignment_id) REFERENCES teaching_assignments(id) ON DELETE CASCADE
);
CREATE TABLE student_pins (
  student_id TEXT NOT NULL,
  pin_hash TEXT NOT NULL,
  failed_attempts INTEGER NOT NULL DEFAULT 0,
  locked_until TEXT,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (student_id),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE student_premises_exit_requests (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  student_id TEXT NOT NULL,
  submitted_by TEXT NOT NULL,
  date TEXT NOT NULL,
  reason TEXT NOT NULL,
  exit_time TEXT NOT NULL,
  planned_return_time TEXT,
  no_return INTEGER NOT NULL DEFAULT 0 CHECK (no_return IN (0,1)),
  return_time TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('{', 'p', 'e', 'n', 'd', 'i', 'n', 'g', ',', 'a', 'p', 'p', 'r', 'o', 'v', 'e', 'd', ',', 'r', 'e', 'j', 'e', 'c', 't', 'e', 'd', '}')),
  approved_by TEXT,
  approved_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (approved_by) REFERENCES profiles(id) ON DELETE SET NULL,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE RESTRICT,
  FOREIGN KEY (submitted_by) REFERENCES profiles(id) ON DELETE RESTRICT
);
CREATE TABLE student_wallets (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  student_id TEXT NOT NULL,
  daily_limit NUMERIC,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  CHECK (((daily_limit IS NULL) OR (daily_limit > (0)))),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  UNIQUE (student_id)
);
CREATE TABLE students (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  student_code TEXT NOT NULL,
  national_id TEXT,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  department_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'studying' CHECK (status IN ('{', 's', 't', 'u', 'd', 'y', 'i', 'n', 'g', ',', 't', 'r', 'a', 'n', 's', 'f', 'e', 'r', 'r', 'e', 'd', ',', 'g', 'r', 'a', 'd', 'u', 'a', 't', 'e', 'd', ',', 'd', 'r', 'o', 'p', 'p', 'e', 'd', '}')),
  profile_id TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  grade_level_id TEXT,
  prefix TEXT,
  phone TEXT,
  email TEXT,
  family_status TEXT,
  chronic_disease TEXT,
  drug_allergy TEXT,
  food_allergy TEXT,
  blood_type TEXT CHECK (blood_type IN ('{', 'A', '+', ',', 'A', '-', ',', 'B', '+', ',', 'B', '-', ',', 'A', 'B', '+', ',', 'A', 'B', '-', ',', 'O', '+', ',', 'O', '-', ',', 'u', 'n', 'k', 'n', 'o', 'w', 'n', '}')),
  house_no TEXT,
  village_no TEXT,
  alley TEXT,
  road TEXT,
  subdistrict TEXT,
  district TEXT,
  province TEXT,
  postal_code TEXT,
  date_of_birth TEXT,
  avatar_path TEXT,
  latitude REAL,
  longitude REAL,
  PRIMARY KEY (id),
  FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE RESTRICT,
  FOREIGN KEY (grade_level_id) REFERENCES grade_levels(id) ON DELETE RESTRICT,
  CHECK (((latitude >= ('-90')) AND (latitude <= (90)))),
  CHECK (((longitude >= ('-180')) AND (longitude <= (180)))),
  UNIQUE (national_id),
  FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE SET NULL,
  UNIQUE (profile_id),
  UNIQUE (student_code)
);
CREATE TABLE study_map_assignments (
  plan_subject_id TEXT NOT NULL,
  grade_level_id TEXT NOT NULL,
  map_id TEXT NOT NULL,
  PRIMARY KEY (plan_subject_id, grade_level_id),
  FOREIGN KEY (grade_level_id) REFERENCES grade_levels(id) ON DELETE CASCADE,
  FOREIGN KEY (map_id) REFERENCES study_map_library(id),
  FOREIGN KEY (plan_subject_id) REFERENCES plan_subjects(id) ON DELETE CASCADE
);
CREATE TABLE study_map_library (
  id TEXT NOT NULL,
  theme TEXT NOT NULL DEFAULT 'forest',
  name TEXT NOT NULL,
  PRIMARY KEY (id),
  CHECK ((id = 'forest')),
  CHECK (((length(trim(name)) >= 1) AND (length(trim(name)) <= 100))),
  CHECK ((theme = 'forest'))
);
CREATE TABLE study_plans (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  UNIQUE (code)
);
CREATE TABLE subject_cover_library (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);
CREATE TABLE subjects (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  code TEXT NOT NULL,
  name_th TEXT NOT NULL,
  name_en TEXT,
  learning_area_id TEXT NOT NULL,
  subject_type TEXT NOT NULL CHECK (subject_type IN ('{', 'b', 'a', 's', 'i', 'c', ',', 'a', 'd', 'd', 'i', 't', 'i', 'o', 'n', 'a', 'l', ',', 'a', 'c', 't', 'i', 'v', 'i', 't', 'y', '}')),
  credits NUMERIC NOT NULL,
  hours_per_week INTEGER NOT NULL,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  department_id TEXT NOT NULL,
  suggested_grade_level_id TEXT,
  suggested_term INTEGER,
  grading_method TEXT NOT NULL DEFAULT 'graded' CHECK (grading_method IN ('{', 'g', 'r', 'a', 'd', 'e', 'd', ',', 'p', 'a', 's', 's', '_', 'f', 'a', 'i', 'l', '}')),
  cover_path TEXT,
  cover_focus_x INTEGER NOT NULL DEFAULT 50,
  cover_focus_y INTEGER NOT NULL DEFAULT 50,
  scene_theme TEXT NOT NULL DEFAULT 'forest',
  cover_id TEXT,
  PRIMARY KEY (id),
  CHECK (((cover_focus_x >= 0) AND (cover_focus_x <= 100))),
  CHECK (((cover_focus_y >= 0) AND (cover_focus_y <= 100))),
  FOREIGN KEY (cover_id) REFERENCES subject_cover_library(id) ON DELETE RESTRICT,
  UNIQUE (department_id, code),
  FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE RESTRICT,
  FOREIGN KEY (learning_area_id) REFERENCES learning_areas(id) ON DELETE RESTRICT,
  FOREIGN KEY (suggested_grade_level_id) REFERENCES grade_levels(id) ON DELETE SET NULL,
  CHECK (((suggested_term IS NULL) OR (suggested_term IN (1, 2))))
);
CREATE TABLE submission_attachments (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  submission_id TEXT NOT NULL,
  storage_path TEXT NOT NULL,
  file_name TEXT NOT NULL,
  uploaded_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (submission_id) REFERENCES assignment_submissions(id) ON DELETE CASCADE
);
CREATE TABLE teaching_assignment_teachers (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  assignment_id TEXT NOT NULL,
  teacher_id TEXT NOT NULL,
  from_date TEXT NOT NULL,
  to_date TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (assignment_id) REFERENCES teaching_assignments(id) ON DELETE CASCADE,
  CHECK (((to_date IS NULL) OR (to_date >= from_date))),
  FOREIGN KEY (teacher_id) REFERENCES profiles(id) ON DELETE RESTRICT
);
CREATE TABLE teaching_assignments (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  teacher_id TEXT,
  subject_id TEXT NOT NULL,
  classroom_id TEXT NOT NULL,
  academic_year INTEGER NOT NULL,
  term INTEGER,
  periods_per_week INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  group_id TEXT,
  score_collect_pct INTEGER,
  score_exam_pct INTEGER,
  split_exam_items INTEGER NOT NULL DEFAULT 0 CHECK (split_exam_items IN (0,1)),
  plan_group_id TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (classroom_id) REFERENCES classrooms(id) ON DELETE RESTRICT,
  CHECK ((((score_collect_pct IS NULL) = (score_exam_pct IS NULL)) AND ((score_collect_pct IS NULL) OR ((score_collect_pct + score_exam_pct) = 100)))),
  FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE RESTRICT,
  FOREIGN KEY (teacher_id) REFERENCES profiles(id) ON DELETE RESTRICT,
  CHECK (((term IS NULL) OR (term IN (1, 2))))
);
CREATE TABLE teaching_plan_slot_topics (
  slot_id TEXT NOT NULL,
  topic_id TEXT NOT NULL,
  position INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (slot_id, topic_id),
  FOREIGN KEY (slot_id) REFERENCES teaching_plan_slots(id) ON DELETE CASCADE,
  FOREIGN KEY (topic_id) REFERENCES plan_topics(id) ON DELETE CASCADE
);
CREATE TABLE teaching_plan_slots (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  teaching_assignment_id TEXT NOT NULL,
  slot_date TEXT NOT NULL,
  period_no INTEGER NOT NULL,
  completed_at TEXT,
  completed_on_plan INTEGER CHECK (completed_on_plan IN (0,1)),
  note TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  CHECK (((completed_at IS NULL) = (completed_on_plan IS NULL))),
  CHECK ((period_no > 0)),
  FOREIGN KEY (teaching_assignment_id) REFERENCES teaching_assignments(id) ON DELETE CASCADE,
  UNIQUE (teaching_assignment_id, slot_date, period_no)
);
CREATE TABLE teaching_plan_units (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  teaching_assignment_id TEXT NOT NULL,
  unit_no INTEGER NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  completed_at TEXT,
  completed_on_plan INTEGER CHECK (completed_on_plan IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  note TEXT,
  PRIMARY KEY (id),
  CHECK (((completed_at IS NULL) = (completed_on_plan IS NULL))),
  FOREIGN KEY (teaching_assignment_id) REFERENCES teaching_assignments(id) ON DELETE CASCADE,
  UNIQUE (teaching_assignment_id, unit_no),
  CHECK ((unit_no > 0))
);
CREATE TABLE time_clock_records (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  profile_id TEXT NOT NULL,
  date TEXT NOT NULL,
  clock_in_time TEXT,
  clock_in_lat REAL,
  clock_in_lng REAL,
  clock_out_time TEXT,
  clock_out_lat REAL,
  clock_out_lng REAL,
  recorded_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  auto_clock_out INTEGER NOT NULL DEFAULT 0 CHECK (auto_clock_out IN (0,1)),
  PRIMARY KEY (id),
  UNIQUE (profile_id, date),
  FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE RESTRICT,
  FOREIGN KEY (recorded_by) REFERENCES profiles(id) ON DELETE RESTRICT
);
CREATE TABLE transfer_intakes (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  student_id TEXT NOT NULL,
  source_school TEXT NOT NULL,
  intake_date TEXT NOT NULL DEFAULT (date('now')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  UNIQUE (student_id)
);
CREATE TABLE tuition_invoices (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  student_id TEXT NOT NULL,
  term_id TEXT NOT NULL,
  title TEXT NOT NULL,
  amount NUMERIC NOT NULL,
  due_date TEXT,
  status TEXT NOT NULL DEFAULT 'open',
  file_path TEXT,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  CHECK ((amount > (0))),
  FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE RESTRICT,
  CHECK ((status IN ('open', 'cancelled'))),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE RESTRICT,
  FOREIGN KEY (term_id) REFERENCES academic_terms(id) ON DELETE RESTRICT
);
CREATE TABLE tuition_payments (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  invoice_id TEXT NOT NULL,
  receipt_no INTEGER NOT NULL,
  amount NUMERIC NOT NULL,
  method TEXT NOT NULL,
  paid_at TEXT NOT NULL DEFAULT (date('now')),
  note TEXT,
  voided_at TEXT,
  void_reason TEXT,
  recorded_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  CHECK ((amount > (0))),
  CHECK (((voided_at IS NULL) = (void_reason IS NULL))),
  FOREIGN KEY (invoice_id) REFERENCES tuition_invoices(id) ON DELETE RESTRICT,
  CHECK ((method IN ('cash', 'transfer', 'other'))),
  UNIQUE (receipt_no),
  FOREIGN KEY (recorded_by) REFERENCES profiles(id) ON DELETE RESTRICT
);
CREATE TABLE tuition_term_amounts (
  term_id TEXT NOT NULL,
  amount NUMERIC NOT NULL,
  updated_by TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  PRIMARY KEY (term_id),
  CHECK ((amount > (0))),
  UNIQUE (id),
  FOREIGN KEY (term_id) REFERENCES academic_terms(id) ON DELETE CASCADE,
  FOREIGN KEY (updated_by) REFERENCES profiles(id) ON DELETE RESTRICT
);

