CREATE VIEW exam_questions_for_attempt AS SELECT id,
    subject_id,
    question_type,
    prompt,
    points,
    created_by,
    created_at,
    updated_at,
    prompt_json
   FROM exam_questions;
CREATE VIEW exam_question_choices_for_attempt AS SELECT id,
    question_id,
    label,
    "position",
    label_json
   FROM exam_question_choices;
